import { RandomState } from '@studio/engine/random/random-state';
import { referencePuzzlesToCheck } from '@studio/engine/reference-puzzles';
import { decodeParams } from '../params';
import { slantedGame as game } from '../slanted-game';
import { encodeSolution } from '../solution';
import reference from '../testing/reference-puzzles.json';
import { generateSlanted } from './generate';

/**
 * The recorded puzzles were generated by the original C code (see
 * tools/c-reference). The port must reproduce each one exactly: the
 * puzzle, its solution (which completes it), and the solver finding that
 * solution from the puzzle alone (as Solve does for a puzzle typed in by
 * hand). `npm test` checks a sample, `npm run test:puzzles` all of them.
 */
describe('Slanted matches the original C code', () => {
  for (const ref of referencePuzzlesToCheck(reference)) {
    it(`${ref.params}#${ref.seed}`, () => {
      const params = decodeParams(ref.params);
      const puzzle = generateSlanted(params, new RandomState(ref.seed));
      expect(puzzle.description).toBe(ref.description);
      expect(puzzle.solution).toBe(ref.solution);

      const initial = game.newGame(params, ref.description);
      const solved = game.applyMove(initial, game.solve(initial, ref.solution)!)!;
      expect([solved.completed, solved.cheated]).toEqual([true, true]);
      const move = game.solve(initial);
      expect(move?.kind).toBe('solve');
      if (move?.kind === 'solve') expect(encodeSolution(move.slashes)).toBe(ref.solution);
    });
  }
});
